/**
 * Interactive Learning V4 — the Visual Teaching Block Registry (`teaching-blocks/1.1.0`).
 *
 * One registry for every subject. A lesson (authored, generated by the Curriculum V2 / Content Factory
 * pipeline, or a design-preview demo) may only use block types listed here, and every block is checked
 * against its entry before it can be rendered:
 *
 *   schema         strict content schema (unknown keys rejected; no answer/solution/correct* keys: formative
 *                  expectations are named `formativeKey`, the same convention as Curriculum V2 items)
 *   semantics      model consistency, e.g. a fraction comparison's key must equal the computed relation and a
 *                  triangle's labelled sides must match its drawn geometry
 *   fit            subject family and grade band the block was designed and tested for
 *   accessibility  keyboard/touch/screen-reader operation and a text equivalent (`textAlternative`)
 *   offline        every block renders from the cached lesson; nothing is downloaded at view time
 *   feedback       none, authored, misconception-linked or derived from the block's own model
 *   assessment     FORMATIVE_ONLY for every block: no block scores, writes evidence or mastery; mastery goes
 *                  through the scene's ASSESSMENT_HANDOFF to Assessment Player V2
 *   provenance     blocks that carry a text source (reading passage, historical source) must state its `origin`
 *                  (kind, licence, attribution); the key is not named "provenance" because generated content may
 *                  never assert provenance (the strict candidate parser rejects that key)
 *
 * The registry is data plus pure functions, so the generation brief, the strict parser, the validator, the
 * player and the tests all read the same definitions.
 */
import { z } from "zod";
import { PLACES, type PlaceId } from "@/lib/learner-experience/demo/placeValue";
import { compare, fractionTex, isValidFraction } from "./models/fractions";
import { describeShape, shapeArea, shapePerimeter, shapeProblems, SHAPE_VIEWS, type ShapeSpec } from "./models/geometry";
import { QUANTITIES } from "./models/numericResponse";
import { LIBERIA_COUNTIES } from "./models/liberiaCounties";
import { plainMathText } from "@/lib/learner-experience/math/tex";

export const TEACHING_BLOCK_REGISTRY_VERSION = "teaching-blocks/1.1.0" as const;

/** Subject families the registry reasons about; curriculum subject codes map onto them. */
export const SUBJECT_FAMILIES = ["MATHEMATICS", "SCIENCE", "HUMANITIES", "LANGUAGE"] as const;
export type SubjectFamily = (typeof SUBJECT_FAMILIES)[number];

export function subjectFamily(subject: string): SubjectFamily | null {
  const code = subject.trim().toUpperCase().replace(/[\s-]+/g, "_");
  if (/^(MATH|MATHS|MATHEMATICS)$/.test(code)) return "MATHEMATICS";
  if (/^(SCIENCE|GENERAL_SCIENCE|BIOLOGY|CHEMISTRY|PHYSICS|AGRICULTURE)$/.test(code)) return "SCIENCE";
  if (/^(SOCIAL_STUDIES|CIVICS|HISTORY|GEOGRAPHY)$/.test(code)) return "HUMANITIES";
  if (/^(ENGLISH|LITERACY|LITERATURE|LANGUAGE_ARTS|READING)$/.test(code)) return "LANGUAGE";
  return null;
}

// ── Schemas ────────────────────────────────────────────────────────────────

const id = z.string().regex(/^[a-z0-9][a-z0-9-]{0,63}$/, "block_id_format");
const line = z.string().trim().min(1).max(600);
const para = z.string().trim().min(1).max(2400);
const num = z.number().finite();
const whole = (min: number, max: number) => z.number().int().min(min).max(max);
const option = z.strictObject({ id, text: line, feedback: line });
const fraction = z.strictObject({ numerator: whole(0, 48), denominator: whole(1, 24) });
const placeId = z.enum(PLACES.map((place) => place.id) as [PlaceId, ...PlaceId[]]);
const unitSchema = z.strictObject({ kind: z.enum(["LENGTH", "AREA", "NONE"]), base: z.string().max(12) });
const origin = z.strictObject({
  kind: z.enum(["ORIGINAL_FOR_LIBERIALEARN", "PUBLIC_DOMAIN", "OPENLY_LICENSED", "LICENSED_WITH_PERMISSION"]),
  license: line,
  attribution: line,
  note: line.optional(),
});
const shape = z.discriminatedUnion("kind", [
  z.strictObject({ kind: z.literal("RECTANGLE"), length: num.positive().max(10_000), width: num.positive().max(10_000), unit: z.string().min(1).max(8) }),
  z.strictObject({ kind: z.literal("TRIANGLE"), base: num.positive().max(10_000), height: num.positive().max(10_000), apexOffset: num.min(-10_000).max(10_000), unit: z.string().min(1).max(8), sideLabels: z.tuple([num.positive(), num.positive()]).optional() }),
  z.strictObject({ kind: z.literal("COMPOSITE"), rects: z.array(z.strictObject({ x: whole(0, 30), y: whole(0, 30), w: whole(1, 30), h: whole(1, 30) })).min(1).max(6), unit: z.string().min(1).max(8) }),
]);
const views = z.array(z.enum(SHAPE_VIEWS)).max(4);
const check = z.strictObject({ id, prompt: line, options: z.array(option).min(2).max(6), formativeKey: z.strictObject({ expectedOptionId: id }), hint: line.optional(), misconceptionId: id.optional() });

