export type BlockType = keyof typeof BLOCK_SCHEMAS;
export type VisualBlock = { [K in BlockType]: z.infer<(typeof BLOCK_SCHEMAS)[K]> }[BlockType];
export type BlockOf<K extends BlockType> = Extract<VisualBlock, { type: K }>;

// ── Registry entries ───────────────────────────────────────────────────────

export type RegistryEntry = Readonly<{
  type: BlockType;
  since: "teaching-blocks/1.0.0" | "teaching-blocks/1.1.0";
  label: string;
  /** What learning move the block serves (shown in the generation brief). */
  purpose: string;
  subjects: readonly SubjectFamily[] | "ANY";
  grades: readonly [number, number];
  interactive: boolean;
  /**
   * EXPLANATION is watched or read; EXPLORATION is hands-on input (manipulating a model, exploring a map, sustained
   * reading) and still counts as instruction; PRACTICE is solving, deciding or producing, and counts as activity.
   */
  engagement: "EXPLANATION" | "EXPLORATION" | "PRACTICE";
  feedback: "NONE" | "AUTHORED" | "MISCONCEPTION_LINKED" | "DERIVED_FROM_MODEL";
  keyPolicy: "NONE" | "FORMATIVE_LOCAL";
  assessment: "FORMATIVE_ONLY";
  offline: "FULL";
  provenance: "NOT_APPLICABLE" | "REQUIRED";
  /** Narrowest canvas (CSS px) the block stays fully usable at without horizontal scrolling. */
  minInlineSize: number;
  /** Rough learner time, used only for the explanation/activity balance report. */
  seconds: (block: VisualBlock) => number;
}>;

const ALL_GRADES = [1, 12] as const;
