export const BLOCK_TYPES = Object.freeze(Object.keys(BLOCK_SCHEMAS) as BlockType[]);

/** Blocks a learner must finish before Continue. */
export function blockRequiresCompletion(block: VisualBlock): boolean {
  switch (block.type) {
    case "STEP_REVEAL": case "WORKED_SOLUTION": case "CHECK": case "DIGIT_CARDS": case "SORT": case "SEQUENCE": case "NUMERIC_RESPONSE":
    case "MISTAKE_ANALYSIS": case "FRACTION_NUMBER_LINE": case "FRACTION_COMPARE": case "PREDICT_OBSERVE": case "SOURCE_EVIDENCE":
    case "SENTENCE_BUILDER": case "WRITING_ORGANIZER": return true;
    case "FRACTION_MODEL": return block.interaction === "SHADE_TARGET";
    case "AREA_MODEL": return block.mode === "FILL";
    case "MAP_EXPLORER": return Boolean(block.task);
    default: return false;
  }
}

export function blockId(block: VisualBlock): string | null {
  return "id" in block ? block.id : null;
}

// ── Validation ─────────────────────────────────────────────────────────────

export type BlockContext = Readonly<{ subject: string; grade: number }>;

/** Model and content consistency that a schema cannot express. Returns problem codes. */
export function blockSemantics(block: VisualBlock): string[] {
  const problems: string[] = [];
  const at = (code: string) => problems.push(`${code}:${blockId(block) ?? block.type}`);
  const optionKey = (options: readonly { id: string }[], expected: string) => { if (!options.some((candidate) => candidate.id === expected)) at("formative_key_unknown_option"); if (new Set(options.map((candidate) => candidate.id)).size !== options.length) at("option_id_duplicate"); };
  switch (block.type) {
    case "SORT": { const groups = new Set(block.groups.map((group) => group.id)); for (const card of block.cards) if (!groups.has(card.group)) at("sort_card_group_unknown"); break; }
    case "CHECK": for (const item of block.items) optionKey(item.options, item.formativeKey.expectedOptionId); break;
    case "MISTAKE_ANALYSIS": case "PREDICT_OBSERVE": optionKey(block.options, block.formativeKey.expectedOptionId); break;
    case "WORKED_SOLUTION": if (block.shape) for (const code of shapeProblems(block.shape as ShapeSpec)) at(code); break;
    case "SHAPE_MODEL": {
      for (const code of shapeProblems(block.shape as ShapeSpec)) at(code);
      if (block.adjustable && (block.shape.kind !== "RECTANGLE" || block.adjustable.min >= block.adjustable.max)) at("shape_adjustable_invalid");
      break;
    }
    case "NUMERIC_RESPONSE": {
      if (block.shape) for (const code of shapeProblems(block.shape as ShapeSpec)) at(code);
      // Independent problems keep help out of reach until the learner has tried: no hints.
      if (block.mode === "INDEPENDENT" && block.hints.length > 0) at("independent_problem_has_hints");
      if (block.mode === "GUIDED" && block.hints.length === 0) at("guided_problem_requires_hints");
      for (const part of block.parts) {
        // A shape-bound area or perimeter key must equal the shape's own computed value.
        if (block.shape && part.quantity === "AREA" && Math.abs(part.formativeKey.value - shapeArea(block.shape as ShapeSpec)) > 1e-6) at("numeric_key_disagrees_with_shape_area");
        if (block.shape && part.quantity === "PERIMETER") { const perimeter = shapePerimeter(block.shape as ShapeSpec); if (perimeter === null || Math.abs(part.formativeKey.value - perimeter) > 1e-6) at("numeric_key_disagrees_with_shape_perimeter"); }
        if ((part.quantity === "AREA") !== (part.unit.kind === "AREA") && part.unit.kind !== "NONE") at("numeric_unit_kind_mismatch");
        if (part.misconceptions.some((entry) => Math.abs(entry.value - part.formativeKey.value) < 1e-9)) at("misconception_value_equals_key");
      }
      break;
    }
    case "FRACTION_MODEL":
      if (block.shaded > block.parts) at("fraction_shaded_exceeds_parts");
      if (block.interaction === "SHADE_TARGET" && (!block.target || block.target.numerator > block.target.denominator)) at("fraction_target_invalid");
      break;
    case "FRACTION_EQUIVALENCE": if (!isValidFraction(block.base) || block.base.numerator > block.base.denominator || block.factors.some((factor) => factor * block.base.denominator > 24)) at("fraction_equivalence_out_of_range"); break;
    case "FRACTION_NUMBER_LINE": if (block.formativeKey.numerator > block.formativeKey.denominator * block.wholes || block.denominator % block.formativeKey.denominator !== 0) at("number_line_key_not_on_ticks"); break;
    case "FRACTION_COMPARE": if (compare(block.a, block.b) !== block.formativeKey.relation) at("fraction_compare_key_wrong"); break;
    case "AREA_MODEL":
      if (block.splitA && block.splitA.reduce((sum, value) => sum + value, 0) !== block.factorA) at("area_model_split_a_wrong");
      if (block.splitB && block.splitB.reduce((sum, value) => sum + value, 0) !== block.factorB) at("area_model_split_b_wrong");
      break;
    case "PARTICLE_MODEL": if (!(block.minC < block.maxC) || block.startC < block.minC || block.startC > block.maxC) at("particle_range_invalid"); break;
    case "MAP_EXPLORER": if (block.task && !LIBERIA_COUNTIES.some((county) => county.id === block.task!.formativeKey.regionId)) at("map_region_unknown"); break;
    case "SOURCE_EVIDENCE": { const supporting = block.sentences.filter((sentence) => sentence.supports).length; if (supporting < block.minSelect) at("evidence_min_select_exceeds_supporting"); if (supporting === block.sentences.length) at("evidence_requires_distractors"); break; }
    case "SENTENCE_BUILDER": { const tiles = [...block.tiles].sort().join("\u0000"); if (block.formativeKey.orders.some((order) => [...order].sort().join("\u0000") !== tiles)) at("sentence_order_uses_other_tiles"); break; }
    case "DATA_PLOT": if (block.series.some((point, index) => index > 0 && point.x < block.series[index - 1].x)) at("data_points_not_ordered"); break;
    default: break;
  }
  return problems;
}

/** Strict parse plus semantics and subject/grade fit. `problems` empty means the block may be rendered. */
export function validateBlock(input: unknown, context?: BlockContext): { block: VisualBlock | null; problems: string[] } {
  const type = typeof input === "object" && input !== null && "type" in input ? String((input as { type: unknown }).type) : "";
  if (!(type in BLOCK_SCHEMAS)) return { block: null, problems: [`block_type_unsupported:${type || "missing"}`] };
  const parsed = BLOCK_SCHEMAS[type as BlockType].safeParse(input);
  if (!parsed.success) return { block: null, problems: parsed.error.issues.slice(0, 5).map((issue) => `block_schema:${type}:${issue.path.join(".") || "$"}:${issue.message}`) };
  const block = parsed.data as VisualBlock;
  const problems = blockSemantics(block);
  if (context) {
    const registered = TEACHING_BLOCK_REGISTRY[block.type];
    const family = subjectFamily(context.subject);
    if (registered.subjects !== "ANY" && (!family || !registered.subjects.includes(family))) problems.push(`block_subject_unfit:${block.type}:${context.subject}`);
    if (context.grade < registered.grades[0] || context.grade > registered.grades[1]) problems.push(`block_grade_unfit:${block.type}:${context.grade}`);
  }
  return { block, problems };
}

// ── Text equivalents (screen readers, read-aloud, text-only and offline fallback) ───────────────

const fractionText = (value: { numerator: number; denominator: number }) => `${value.numerator}/${value.denominator}`;

/** Everything a block teaches, as plain text. Never includes a formative key before the learner answers. */
export function blockTextAlternative(block: VisualBlock): string {
  switch (block.type) {
    case "GROUPED_NUMBER": case "PLACE_VALUE_CHART": return `${block.value.toLocaleString("en-US")}. ${block.caption}`;
    case "TEN_TIMES": return block.caption;
    case "NUMBER_BUILDER": return block.task ?? "Build a number place by place.";
    case "DIGIT_CARDS": return block.prompt;
    case "STEP_REVEAL": return [block.question, ...block.steps.map((step, index) => `Step ${index + 1}: ${step.text}`)].join(" ");
    case "PROCESS_CYCLE": return `${block.title}: ${block.stages.map((stage) => `${stage.label}. ${stage.detail}`).join(" ")}`;
    case "SORT": return `${block.prompt} Groups: ${block.groups.map((group) => group.label).join(", ")}. Cards: ${block.cards.map((card) => card.text).join(", ")}.`;
    case "SEQUENCE": return `${block.prompt} ${block.events.map((event) => `${event.marker}: ${event.label}.`).join(" ")}`;
    case "CALLOUT": return `${block.title}. ${plainMathText(block.text)}`;
    case "CHECK": return block.items.map((item) => `${plainMathText(item.prompt)} Options: ${item.options.map((candidate) => plainMathText(candidate.text)).join("; ")}.`).join(" ");
    case "EQUATION": return `${plainMathText(`$${block.tex}$`)}${block.caption ? `. ${block.caption}` : ""}`;
    case "WORKED_SOLUTION": return [plainMathText(block.problem), block.shape ? describeShape(block.shape as ShapeSpec) : "", ...block.steps.map((step, index) => `Step ${index + 1}: ${plainMathText(step.text)}${step.tex ? ` ${plainMathText(`$${step.tex}$`)}` : ""}`)].filter(Boolean).join(" ");
    case "NUMERIC_RESPONSE": return [plainMathText(block.prompt), block.shape ? describeShape(block.shape as ShapeSpec).split(". Area")[0] + "." : "", ...block.parts.map((part) => `${part.label}: write your answer${part.unit.kind === "NONE" ? "" : " with its unit"}.`)].filter(Boolean).join(" ");
    case "MISTAKE_ANALYSIS": return `${plainMathText(block.problem)} ${block.attempt.name} wrote: ${block.attempt.steps.map(plainMathText).join(" ")} ${block.question} Options: ${block.options.map((candidate) => candidate.text).join("; ")}.`;
    case "SHAPE_MODEL": return `${describeShape(block.shape as ShapeSpec)} ${block.caption}`;
    case "FRACTION_MODEL": return `A ${block.representation === "BAR" ? "bar" : "circle"} split into ${block.parts} equal parts with ${block.shaded} shaded: ${fractionText({ numerator: block.shaded, denominator: block.parts })}. ${block.caption}`;
    case "FRACTION_EQUIVALENCE": return `${fractionText(block.base)} is the same amount as ${block.factors.map((factor) => fractionText({ numerator: block.base.numerator * factor, denominator: block.base.denominator * factor })).join(", ")}. ${block.caption}`;
    case "FRACTION_NUMBER_LINE": return `${block.prompt} A number line from 0 to ${block.wholes} marked in ${block.denominator}ths.`;
    case "FRACTION_COMPARE": return `${block.prompt} Compare ${fractionText(block.a)} and ${fractionText(block.b)}.`;
    case "ARRAY_MODEL": return `${block.rows} ${block.context?.group ?? "rows"} of ${block.columns} ${block.context?.item ?? "dots"}: ${block.rows} × ${block.columns} = ${block.rows * block.columns}. ${block.caption}`;
    case "AREA_MODEL": return `${block.prompt} Find ${block.factorA} × ${block.factorB} by splitting it into parts.`;
    case "PARTICLE_MODEL": return `${block.caption} Below 0 °C water is a solid: particles packed in a pattern, vibrating in place. From 0 °C to 100 °C it is a liquid: particles close together, sliding past one another. At 100 °C and above it is a gas: particles far apart, moving quickly in all directions.`;
    case "PREDICT_OBSERVE": return `${block.prompt} Options: ${block.options.map((candidate) => candidate.text).join("; ")}. After you predict, the observation is shown. ${block.explainPrompt}`;
    case "DATA_PLOT": return `${block.title}. ${block.series.map((point) => `${block.x.label} ${point.x}${block.x.unit ? ` ${block.x.unit}` : ""}: ${block.y.label} ${point.y}${block.y.unit ? ` ${block.y.unit}` : ""}`).join("; ")}. ${block.caption}`;
    case "MAP_EXPLORER": return `${block.task ? `${block.task.prompt} ` : ""}A schematic map of Liberia's 15 counties: ${LIBERIA_COUNTIES.map((county) => `${county.name} (capital ${county.capital})`).join(", ")}.`;
    case "SOURCE_EVIDENCE": return `${block.source.title}. ${block.sentences.map((sentence) => sentence.text).join(" ")} ${block.question}`;
    case "READING_PASSAGE": return `${block.title}. ${block.paragraphs.join(" ")}`;
    case "SENTENCE_BUILDER": return `${block.prompt} Word tiles: ${block.tiles.join(", ")}.`;
    case "WRITING_ORGANIZER": return `${block.prompt} ${block.fields.map((field) => `${field.label}: ${field.guidance}`).join(" ")}`;
  }
}

/** The catalogue a generator sees: types, purposes and fit, with the JSON schema of each block. */
export function generationCatalogue(context?: BlockContext): readonly Readonly<{ type: BlockType; label: string; purpose: string; interactive: boolean; engagement: RegistryEntry["engagement"]; feedback: RegistryEntry["feedback"]; provenance: RegistryEntry["provenance"]; schema: unknown }>[] {
  const family = context ? subjectFamily(context.subject) : null;
  return BLOCK_TYPES.map((type) => TEACHING_BLOCK_REGISTRY[type]).filter((registered) => !context || ((registered.subjects === "ANY" || (family !== null && registered.subjects.includes(family))) && context.grade >= registered.grades[0] && context.grade <= registered.grades[1]))
    .map((registered) => ({ type: registered.type, label: registered.label, purpose: registered.purpose, interactive: registered.interactive, engagement: registered.engagement, feedback: registered.feedback, provenance: registered.provenance, schema: z.toJSONSchema(BLOCK_SCHEMAS[registered.type]) }));
}

export { fractionTex };
